window.SAQ_PAPER_QUESTIONS["2016-2-nsw"]=[{"number":1,"title":"","stemText":"(14 MARKS) An 87-year-old lady from home presents after slipping and falling down her stairs. She has neck pain, and no other injuries. You are concerned about possible spinal cord injury.","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table detailing signs and mechanism of various spinal cord syndromes (8 marks) Syndrome Signs Mechanism Central Cord Syndrome Anterior Cord Syndrome Brown Sequard Syndrome Posterior Cord Syndrome She has a CT scan performed of her cervical spine. *See images on pages 3 & 4 in separate book*"},{"id":"b","label":"Part B","prompt":"Describe the CT findings (2 marks). On examination you find an incomplete cord injury."},{"id":"c","label":"Part C","prompt":"List 4 things you can do (apart from spinal immobilisation) as secondary prevention of further injury. (4 marks)"}],"propPages":["asset:imgfd758e15d5ed28d1d9","asset:img62aa50caff751d0ab2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":2,"title":"","stemText":"(9 MARKS) A 4-year-old boy with autism presents with his mother having placed a foreign body up his nose. *See image on page 5 in separate book* He is agitated and unco-operative.","parts":[{"id":"a","label":"Part A","prompt":"List the three safest methods of removal in this case. (3 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Before attempting removal by techniques not involving sedation, what steps are necessary in preparation? (2 marks)"},{"id":"c","label":"Part C","prompt":"Due to the child’s agitation and lack of co-operation, there is a failed attempt at removal of the Foreign Body and it can no longer be visualised. What circumstances would indicate the need for consideration of bronchoscopy? (4 marks)"}],"propPages":["asset:img7bbfe924b89062a84d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer –</div><div class=\"answer-line\">Positive Pressure insufflation (Carer or BVM)</div><div class=\"answer-line\">Balloon Catheter extraction – Foley or Fogarty</div><div class=\"answer-line\">Sedation and direct instrumentation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answer must include  -  Explanation to the child and carer and verbal consent.</div><div class=\"answer-line\">Topical application of local anaesthetic vasoconstrictor spray such as</div><div class=\"answer-line\">Lignocaine Hydrochloride/Phenylephrine.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answer -</div><div class=\"answer-line\">Coughing and choking</div><div class=\"answer-line\">Stridor</div><div class=\"answer-line\">Unilateral wheeze</div><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Score  - 4/4 – lose 2 points for any item left out.</div><div class=\"answer-line\">SAQ 2 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 60-year-old woman presents with persistent vertigo.","parts":[{"id":"a","label":"Part A","prompt":"In column 1, list four (4) important diagnoses to consider. In column 2, list historical features suggesting each diagnosis. In column 3, list physical-examination findings suggesting each diagnosis. (12 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">A 60 yr old lady presents with vertigo.</td></tr><tr><td colspan=\"3\">In column 1 list 4 important diagnoses to consider in any patient that presents with persistent</td></tr><tr><td colspan=\"3\">vertigo.</td></tr><tr><td colspan=\"3\">In Column 2 list the historical features that would suggest each diagnosis.</td></tr><tr><td colspan=\"3\">In Column 3 list the findings on physical examination that would suggest each diagnosis.</td></tr><tr><td>Column 1 : diagnosis</td><td>Column 2 : historical features</td><td>Column 3 : signs on</td></tr><tr><td colspan=\"3\">examination</td></tr><tr><td>BPPV</td><td>Intermittent vertigo, worse on</td><td>Normal neurological</td></tr><tr><td>movement, lasts seconds –</td><td>examination</td><td></td></tr><tr><td colspan=\"3\">minutes, but can have ongoing</td></tr><tr><td colspan=\"3\">+ve Hallpike test</td></tr><tr><td colspan=\"3\">disequilibrium after acute</td></tr><tr><td colspan=\"3\">attacks</td></tr><tr><td>Vestibular neuronitis/</td><td>Subacute onset over hours</td><td>Normal cranial nerve</td></tr><tr><td>labyrinthitis</td><td>examination</td><td></td></tr><tr><td colspan=\"3\">Persistent symptoms</td></tr><tr><td colspan=\"3\">+ve head impulse test</td></tr><tr><td colspan=\"3\">Can last several days</td></tr><tr><td colspan=\"3\">Can get hearing loss with</td></tr><tr><td colspan=\"3\">labyrinthitis</td></tr><tr><td>Migranous Vertigo</td><td>Past history of migraines, now</td><td>Diagnosis of exclusion, normal</td></tr><tr><td>increased frequency with</td><td>neurological examination</td><td></td></tr><tr><td colspan=\"3\">vestibular episodes.</td></tr><tr><td colspan=\"3\">Can occur with or without</td></tr><tr><td colspan=\"3\">headache.</td></tr><tr><td>Cerebellar stroke</td><td>Hyperacute onset of vertigo</td><td>Ataxia – gait or truncal</td></tr><tr><td>Occipital headache</td><td>Cerebellar signs – past</td><td></td></tr><tr><td colspan=\"3\">pointing/ disdiadochokinesis</td></tr><tr><td colspan=\"3\">Difficulty walking</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"(10 MARKS) A 15-year-old boy has been transferred to your Emergency Department from a rural hospital. He had been given IV benzylpenicillin for a throat infection 48 hours previously. *See image on page 6 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"Describe the appearance of the rash and give a likely differential diagnosis. (3 marks)"},{"id":"b","label":"Part B","prompt":"Assuming that the underlying cause is a severe drug reaction, outline how you would grade the severity. (2 marks)"},{"id":"c","label":"Part C","prompt":"Outline your management of the patient. (3 marks)"},{"id":"d","label":"Part D","prompt":"What acute complications can develop from this disorder? (2 marks)"}],"propPages":["asset:img415059d84a099bc7bc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">a) A widespread erythematous rash with bullous detachment of the epidermis. Scalded</div><div class=\"answer-line\">skin appearance. Appears to affect at least 40% of body surface area.</div><div class=\"answer-line\">Likely toxic epidermal necrolysis.</div><div class=\"answer-line\">Differential includes Stevens Johnson Syndrome (rash too widespread however),</div><div class=\"answer-line\">staphylococcal scalded skin syndrome, erythematous drug reaction, paraneoplastic</div><div class=\"answer-line\">pemphigus (eg. Lymphoma), erythema multiforme (herpes simplex), erythroderma (no</div><div class=\"answer-line\">mucosal involvement</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">The severity and prognosis of SJS/TEN depends upon the amount of skin detachment</div><div class=\"answer-line\">or &quot;detachable&quot; skin (ie, skin with positive Nikolsky sign). Based upon the percentage of</div><div class=\"answer-line\">the body surface area (BSA) involved, patients can be classified into three severity</div><div class=\"answer-line\">groups [1]:</div><div class=\"answer-line\">●SJS – skin detachment of &lt;10 percent of BSA</div><div class=\"answer-line\">●TEN – skin detachment of &gt;30 percent of BSA</div><div class=\"answer-line\">●SJS/TEN overlap – skin detachment of 10 to 30 percent of BSA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Supportive care is the mainstay of treatment and includes wound care, fluid and electrolyte</div><div class=\"answer-line\">management, nutritional support, ocular care, temperature management, pain control, and</div><div class=\"answer-line\">monitoring or treatment of superinfections</div><div class=\"answer-line\">Infection control measures, including sterile handling, topical antiseptic agents, and</div><div class=\"answer-line\">surveillance cultures of possible sites of superinfection, are important components of</div><div class=\"answer-line\">prevention</div><div class=\"answer-line\">Transfer to intensive therapy or burn unit if possible and extensive skin involvement</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">c) Massive loss of fluids through the denuded skin, electrolyte imbalance,</div><div class=\"answer-line\">hypovolemic shock with renal failure, bacteremia, insulin resistance, hypercatabolic</div><div class=\"answer-line\">state, and multiple organ dysfunction syndrome.</div><div class=\"answer-line\">Patients with Stevens-Johnson syndrome/toxic epidermal necrolysis (SJS/TEN) are at high</div><div class=\"answer-line\">risk of bacterial infection. Sepsis and septic shock, most often caused by S. aureus and P.</div><div class=\"answer-line\">aeruginosa, are the main cause of death in these patients.</div><div class=\"answer-line\">Pulmonary complications (eg, pneumonia, interstitial pneumonitis) are frequent.</div><div class=\"answer-line\">Gastrointestinal complications may result from epithelial necrosis of the esophagus, small</div><div class=\"answer-line\">bowel, or colon</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"(12 MARKS) A 45-year-old man presents post falling of a pushbike and hitting shoulder into road guardrail after sliding. He has left shoulder pain and no other injuries. *See images on pages 7 & 8 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"Describe the attached x-rays and your diagnosis. (2 marks)"},{"id":"b","label":"Part B","prompt":"Describe your method of managing this injury. (4 marks)"},{"id":"c","label":"Part C","prompt":"In what position would you immobilise this joint once the injury has been managed in ED? (2 marks)"},{"id":"d","label":"Part D","prompt":"Name the COMMON complications of this injury. (2 marks)"},{"id":"e","label":"Part E","prompt":"Name 2 UNCOMMON complications that can occur. (2 marks)"}],"propPages":["asset:img729e79acd9574b8c1d","asset:img983463eb26de1d3b0d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Lightbulb appearance of humeral head</div><div class=\"answer-line\">Posterior shoulder dislocation</div><div class=\"answer-line\">No fracture evident</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia, closed reduction attempt under procedural sedation</div><div class=\"answer-line\">Axial traction in line with humerus, gentle pressure on the posteriorly displaced head and slow</div><div class=\"answer-line\">external rotation.</div><div class=\"answer-line\">If reduction fails then OT for reduction under GA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Immobilise in external rotation with slight abduction</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Fractures of glenoid rim, greater tuberosity, lesser tuberosity, and humeral head</div><div class=\"answer-line\">30% recurrent disloations (and these can predispose to degenerative changes)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Subscapularis muscle avulsion from insertion site on lesser tuberosity</div><div class=\"answer-line\">neurovascular injuries uncommon due to the anterior location of the neurovascular bundle.</div><div class=\"answer-line\">SAQ 5 image</div><div class=\"answer-line\">SAQ 5 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"(11 MARKS)\nA 38-year-old female presents with BP 220/125 and a headache.","parts":[{"id":"a","label":"Part A","prompt":"Define Hypertensive emergency. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 6 end organs that might be damaged from severe hypertension and at least one clinical manifestation that you might find on history taking, examination and the appropriate investigation. Name the medication of choice for management of that. (6 marks) Organ Symptom or Sign Investigation"},{"id":"c","label":"Part C","prompt":"List 2 classes of medication, 2 examples of that class and the dose that can be used for the treatment of hypertensive emergencies. (4 marks) Class of Medication Example Dose & Frequency of Treatment"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Systolic &gt;180mmHg or diastolic &gt;110mmHg associated with evidence of end organ damage</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Systolic &gt;180mmHg or diastolic &gt;110mmHg associated with evidence of end organ damage</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Vascular - aorta</td><td>Chest pain</td><td>CT aortogram</td></tr><tr><td>BP disparity between arms</td><td>CXR</td><td></td></tr><tr><td colspan=\"3\">syncope</td></tr><tr><td>kidney</td><td>Nausea, vomiting</td><td>EUC’s</td></tr><tr><td>Reduced urine output</td><td>U/A for proteinuria</td><td></td></tr><tr><td colspan=\"3\">polyuria</td></tr><tr><td>Eye/retina</td><td>Blurred vision</td><td>Fundoscopy with flare or</td></tr><tr><td colspan=\"3\">papilloedema</td></tr><tr><td>brain</td><td>Headache</td><td>CT brain</td></tr><tr><td colspan=\"3\">Syncope</td></tr><tr><td colspan=\"3\">Focal neurological signs</td></tr><tr><td>O&amp;G</td><td>Headache</td><td>U/A</td></tr><tr><td>Increased reflexes</td><td>Uric acid</td><td></td></tr><tr><td colspan=\"3\">pregnancy</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"(11 MARKS) A 3-year-old boy presents to the ED with wheezing and SOB for 2/7. His mother feels that his symptoms are getting progressively worse. His observations are: RR 40, BP 90/50, HR 150 and Sats 92% RA. *See image on page 9 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"List 6 causes of wheezing in a child and 2 historical features that may support that diagnosis. (6 marks) Cause of Wheezing 2 Features on History"},{"id":"b","label":"Part B","prompt":"List 3 abnormalities seen on the chest x-ray. (2 marks)"},{"id":"c","label":"Part C","prompt":"Over the course of his time in ED, RR 50, increased work of breathing, sats 89% on 6L O2, T37.4 and wheezing only on the right upper side. List 4 management priorities. (2 marks)"},{"id":"d","label":"Part D","prompt":"What is the most likely diagnosis? (1 mark)"}],"propPages":["asset:img8858e08c3c16aa124f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 3yo boy presents to the ED with wheezing and SOB for 2/7. His mother feels that his symptoms are</div><div class=\"answer-line\">getting progressively worse.  His observations are: RR 40, BP 90/50, HR 150 and Sats 92% RA.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Collapse of right upper lobe</div><div class=\"answer-line\">Consolidation of right upper lobe</div><div class=\"answer-line\">Raised right hemidiaphragm</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Oxygen via HFNP or PEEP</div><div class=\"answer-line\">IVF</div><div class=\"answer-line\">Trial of bronchodilator</div><div class=\"answer-line\">Organise bronchoscopy</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Inhaled foreign body</div><div class=\"answer-line\">SAQ 7 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"(12 MARKS) A 52-year-old judo exponent presents to you with a laceration and swelling to his left pinna. *See image on page 10 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"Describe the injury. (2 marks)"},{"id":"b","label":"Part B","prompt":"Outline 4 important steps in the management. (4 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) ___________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"For this type of injury, list 6 indications for referral for formal surgical review and repair. (6 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) ___________________________________________________________________________ (5) ___________________________________________________________________________ (6) ___________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"What are the contraindications to drainage of this problem in the ED? (2 marks)"}],"propPages":["asset:imge59af3f586f09a5e4b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer –</div><div class=\"answer-line\">A)  Auricular haematoma to the right pinna with small associated superficial skin tear. There is</div><div class=\"answer-line\">no apparent involvement of the tragus or of the external auditory meatus or canal. The</div><div class=\"answer-line\">overlying skin appears well perfused a this point.</div><div class=\"answer-line\">Score 2/2 – one for th edescription of the lesion and one for the note regarding the lack of</div><div class=\"answer-line\">involvement of the external meatus and tragus.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Drainage of the haematoma</div><div class=\"answer-line\">Assessment for other injury including in the external canal and the medial aspect of the pinna..</div><div class=\"answer-line\">Field block of the pinna</div><div class=\"answer-line\">Pressure dressing post drainage</div><div class=\"answer-line\">Tetanus prophylaxis as appropriate to immunisation status</div><div class=\"answer-line\">Close follow up</div><div class=\"answer-line\">Score 4/4  - lose 2 points for any of the answers in bold not included.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">Answer –</td></tr><tr><td>›</td><td>Large overlying skin avulsion (approximately 5 mm or greater)</td><td></td></tr><tr><td>›</td><td>Severe crush injuries</td><td></td></tr><tr><td>›</td><td>Complete or near-complete avulsions</td><td>or amputations</td></tr><tr><td>›</td><td>Large cartilage defects (approximately 5 mm or greater)</td><td></td></tr><tr><td>›</td><td>Obvious devitalization</td><td></td></tr><tr><td>›</td><td>Large auricular haematomas</td><td></td></tr><tr><td>›</td><td>Wounds that require the removal of more than approximately 5 mm of tissue</td><td></td></tr><tr><td>›</td><td>Significant involvement of the auditory canal</td><td></td></tr><tr><td colspan=\"3\">Score out of 6 points. Lose 2 points for any options in bold not included.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Answer –</div><div class=\"answer-line\">o Haematomas older than 7 days</div><div class=\"answer-line\">o Recurrent or chronic haematomas</div><div class=\"answer-line\">(open surgical debridement indicated because the haematoma, granulation tissue, or both</div><div class=\"answer-line\">can be located within the cartilage instead of in the sub-perichondrial space.)</div><div class=\"answer-line\">Score 2/2.</div><div class=\"answer-line\">SAQ 8 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"(9 MARKS) A 55-year-old male presents after an out of hospital cardiac arrest. He had a 7 minute downtime with effective bystander CPR prior to the arrival of the paramedics. The patient is being hand-bagged via facemask. *See image on page 11 in separate book* Below is the ambulance arrest summary: Time since ALS start Rhythm Action/Drugs 0 minutes VF 200J shock/CPR IV access 2 minutes VF 200J shock/CPR 1mg adrenaline 1:10000\nThe patient arrives at the 3rd minute of the arrest cycle.","parts":[{"id":"a","label":"Part A","prompt":"Fill in the table below for the timing of the next 2 rhythm checks and treatment in that cycle based on the"},{"id":"b","label":"Part B","prompt":"Describe 4 abnormalities in this ECG. (2 marks)"},{"id":"c","label":"Part C","prompt":"What phenomenon indicates that this patient is at high risk of arrhythmias? (1 mark)"},{"id":"d","label":"Part D","prompt":"List 4 management priorities now that the patient has ROSC. (4 marks)\n~END OF PART 1~ TRIAL FELLOWSHIP EXAMINATION\nSt George Hospital 2016.1\nWRITTEN EXAMINATION Short Answer Questions\nPART 2\nInstructions:  There are 3 separate books, each worth 100 marks (for a total of 300 marks).  Time Allowed: 3 hours.  Each booklet should be completed in 1 hour.  All images are reproduced in the accompanying ‘props’ book.  Answer each question on the provided examination paper.  Write your name on each page in the space provided. ~BLANK PAGE~"}],"propPages":["asset:img58a8017b5eb48cc2d6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Time since ALS start</td><td>Rhythm</td><td>Action/Drugs</td></tr><tr><td>4 minutes</td><td>VF</td><td>200J shock/CPR</td></tr><tr><td colspan=\"3\">Amiodarone 300mg</td></tr><tr><td colspan=\"3\">bolus</td></tr><tr><td>6 minutes</td><td>VF</td><td>200J shock/CPR</td></tr><tr><td colspan=\"3\">1mg adrenaline 1:10000</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Anterolateral  ST elevation V1-6</div><div class=\"answer-line\">Q waves/poor R wave progression V2-4</div><div class=\"answer-line\">Reciprocal changes III/avF</div><div class=\"answer-line\">ventricular ectopy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">R on T phenomenon of the ventricular ectopic</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Intubation/airway management</div><div class=\"answer-line\">IVF, inotropes if required, sedation</div><div class=\"answer-line\">Targeted normothermia</div><div class=\"answer-line\">Reperfusion with PCI</div><div class=\"answer-line\">SAQ 9 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 25-year-old man has been brought in to your emergency department after sustaining a knife wound to his neck in an assault.\nHis vital signs and GCS are normal.\n*See image on page 12 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"Describe the injury seen in the picture above: (3 marks)"},{"id":"b","label":"Part B","prompt":"Complete the following table for each of the three zones of the neck. (12 marks) ANATOMICAL STRUCTURES NECK ZONE ANATOMICAL LANDMARKS INVESTIGATION MODALITY WHICH MAY BE INJURED ZONE III ZONE II ZONE I"},{"id":"c","label":"Part C","prompt":"List the indications for emergent intubation of this patient. (5 marks)"}],"propPages":["asset:imgfbb8a21a2193098168"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Mention any three of the following:</div><div class=\"answer-line\">• Large y-shaped or zigzag left lateral neck wound</div><div class=\"answer-line\">• Platysma breached</div><div class=\"answer-line\">• Extends through zones III and II</div><div class=\"answer-line\">• Blood-soaked gauze</div><div class=\"answer-line\">• Soft tissue swelling (suspected expanding haematoma) at the angle of the</div><div class=\"answer-line\">mandible</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>1mark for each correct landmark (max 3)</td><td></td></tr><tr><td>1 mark for angiography (Zone III and Zone I) and 1 mark for operative exploration</td><td></td></tr><tr><td>(max 3)</td><td></td></tr><tr><td>2marks for correct identification of two anatomical structures in each zone (max 6)</td><td></td></tr><tr><td>ANATOMICAL</td><td>ANATOMICAL INVESTIGATION</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Stridor</div><div class=\"answer-line\">• Acute respiratory distress</div><div class=\"answer-line\">• Airway obstruction from blood or secretions</div><div class=\"answer-line\">• Expanding neck haematoma</div><div class=\"answer-line\">• Profound shock</div><div class=\"answer-line\">• Extensive subcutaneous emphysema</div><div class=\"answer-line\">• Altered mental state</div><div class=\"answer-line\">• Tracheal shift</div><div class=\"answer-line\">(Relative indications – no marks for this)</div><div class=\"answer-line\">• Progressive neck swelling</div><div class=\"answer-line\">• Voice changes</div><div class=\"answer-line\">• Progressive symptoms</div><div class=\"answer-line\">• Massive subcutaneous emphysema of the neck</div><div class=\"answer-line\">• Need to transfer symptomatic patient</div><div class=\"answer-line\">• Symptomatic patient with anticipated prolonged time away from ED</div><div class=\"answer-line\">TOTAL:  ___ /20MARKS</div><div class=\"answer-line\">Author: Dr Laura Hutchinson (FACEM Wollongong Hospital)</div><div class=\"answer-line\">Date created: 11/5/16</div><div class=\"answer-line\">Resources: Tintinalli’s Emergency Medicine</div><div class=\"answer-line\">SAQ 10 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A young woman has presented following a deliberate self-poisoning of an unknown amount of venlafaxine. She appeared slightly drowsy on arrival, but was otherwise well. BP 120/70, pulse 80. She was seen by your junior registrar and had agreed to drink 50g of charcoal and was admitted for\n• bservation to a non-monitored bed in your short stay unit.\nYou are called to review her 6 hours later due to a change in her status. She now looks unwell, and you are concerned she may have serotonin syndrome.","parts":[{"id":"a","label":"Part A","prompt":"What are the clinical features of serotonin syndrome? (3 marks)"},{"id":"b","label":"Part B","prompt":"What are the pharmacodynamics effects of venlafaxine? (1 mark)"},{"id":"c","label":"Part C","prompt":"List two errors made by your registrar in the management of this patient. Why were these errors? (2 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"How would you manage her suspected serotonin toxicity? (4 marks)"},{"id":"e","label":"Part E","prompt":"List 3 classes of drugs that can cause serotonin toxicity, with 2 examples from each class. (4 marks) (1) ___________________________________________________________________________\nExample 1. ______________________________________________________________\nExample 2. ______________________________________________________________\n(2) ___________________________________________________________________________\nExample 1. ______________________________________________________________\nExample 2. ______________________________________________________________\n(3) ___________________________________________________________________________\nExample 1. ______________________________________________________________\nExample 2. ______________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">- altered mental state + neuromuscular changes + autonomic changes</div><div class=\"answer-line\">- altered mental state : agitation, confusion, GCS depression, coma ,seizures</div><div class=\"answer-line\">-neuromuscular changes : tremor, myoclonus, hypertonia (esp lower limbs), clonus, ocular clonus</div><div class=\"answer-line\">-autonomic changes  :  hyperthermia, sweating, D&amp;V, hypertension.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">SSRI + noradrenaline reuptake inhibitor</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- high risk delayed seizures, risk of aspiration as given charcoal</div><div class=\"answer-line\">- admitted to general ward, unknown amount of venlafaxine taken , well described dose-dependant</div><div class=\"answer-line\">seizure risk, and CVS instability with very high doses (&gt;8gm).</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">-monitored bed/ HDU</div><div class=\"answer-line\">- benzodiazepines – titrated IV boluses midazolam/diazepam</div><div class=\"answer-line\">- cyproheptadine – note : can increase risk of seizures, therefore give benzodiazepines first, and if</div><div class=\"answer-line\">not improving give cyproheptadine</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">SSRI : fluoxetine, fluvoxamine, paroxetine, citalopram, sertraline, excitalopram</div><div class=\"answer-line\">MAO inhibitors : phenelzine, moclobemide</div><div class=\"answer-line\">Serotonin releasing agents : amphetamines, MDMA, ecstasy</div><div class=\"answer-line\">Misc : lithium, tryptophan</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A four day neonate presents to the Emergency department. The child is shocked. Observations are RR60, HR 190, Capillary refill time centrally is 5 secs. They are responsive to pain.","parts":[{"id":"a","label":"Part A","prompt":"List three antenatal / perinatal risk factors for neonatal sepsis. (3 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Give three differential diagnoses of neonatal collapse other than sepsis. (3 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"What empiric therapy would you commence? Be specific. (3 marks)"},{"id":"d","label":"Part D","prompt":"List 6 investigations you would order. (3 marks)\n(i) ___________________________________________________________________________ (ii) ___________________________________________________________________________ (iii) ___________________________________________________________________________ (iv) ___________________________________________________________________________ (v) ___________________________________________________________________________ (vi) ___________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Maternal colonisation with group B streptococcus</span> (positive high vaginal swabs for GBS), prematurity,</div><div class=\"answer-line\">maternal peri-partum illness / fever / infection, prolonged rupture of membranes (greater than</div><div class=\"answer-line\">24hrs prior to delivery)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Inborn error of metabolism, <span class=\"answer-source-red\">congenital cardiac disease</span>, non-accidental injury</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Move to resuscitation area, cardiac and saturation monitoring, high flow oxygen, IV access, <span class=\"answer-source-red\">fluid </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">bolus 20mls/kg of Normal saline</span>,), IV antibiotics ( must state which one/s) , IV antivirals (( must state</div><div class=\"answer-line\">which one) , dextrose if low BSL</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bloods (FBC, UEC, Blood culture</div><div class=\"answer-line\">FBC</div><div class=\"answer-line\">UEC</div><div class=\"answer-line\">Blood cultures</div><div class=\"answer-line\">Bedside glucose, chest xray</div><div class=\"answer-line\">VBG</div><div class=\"answer-line\">LP - delayed</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 33-year-old man presents following a single punch knocking him to the ground. He had a GCS of 7\n• n arrival and has been intubated prior to CT scan.\nHe has returned to the ED following CT of his brain and cervical spine. CT of the cervical spine is normal and he has no other injuries. His current observations are pulse 60/min and BP 155/85 mmHg. His pupils are equal and reactive. A single image from his brain CT is attached: *See image on page 13 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"Describe 3 abnormalities on the CT image. (2 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ The neurosurgical team is en route to hospital and the patient will be going to the operating theatre\nin approximately 1 hour."},{"id":"b","label":"Part B","prompt":"Assuming his clinical status remain unchanged, describe 8 treatments and their therapeutic target which should be performed in the ED prior to transferring this patient to theatre (8 marks) Treatment Therapeutic Target 30 minutes later his left pupil becomes fixed and dilated. His pulse rate is 50/min and his BP 160/100"},{"id":"c","label":"Part C","prompt":"Describe two additional treatments, with dosage where relevant, that you would immediately institute. (2 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________"}],"propPages":["asset:imgdf57073e24bd8f120a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1.1.</div><div class=\"answer-line\">………acute right subdural haematoma…………………………………………..</div><div class=\"answer-line\">1.2. …………midline shift to the left……………………………………………………..</div><div class=\"answer-line\">1.3 …………effacement of R lateral ventricle………………………………………………………..</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Treatment</td><td>Therapeutic target</td><td></td></tr><tr><td>1</td><td>Maintain low end normocarbia</td><td>Adjust TV and RR to achieve pCO2 35-45</td></tr><tr><td>2</td><td>Position 30 degrees head up</td><td>Prevent further raised ICP from venous pressure</td></tr><tr><td>3</td><td>Ensure ETT ties and cervical collar not tight</td><td>ditto</td></tr><tr><td colspan=\"3\">Maintain normoglycaemia – dextrose or</td></tr><tr><td>4</td><td>Keep by BSL between 6-10mmol/L</td><td></td></tr><tr><td colspan=\"3\">insulin as needed</td></tr><tr><td colspan=\"3\">Keep core temperature between 35-37 degrees with</td></tr><tr><td>5</td><td>Maintain normothermia</td><td></td></tr><tr><td colspan=\"3\">Bair Hugger, warm fluids or antipyretics</td></tr><tr><td colspan=\"3\">Maintain optimal BP with fluids (N saline</td></tr><tr><td>6</td><td>Keep MAP between 70-85mmHg</td><td></td></tr><tr><td colspan=\"3\">500ml boluses) or vasopressors as indicated.</td></tr><tr><td colspan=\"3\">Avoid  hypertension (see below)</td></tr><tr><td colspan=\"3\">Avoid/treat  hypertension, agitated, coughing,</td></tr><tr><td colspan=\"3\">Ensure adequate sedation and paralysis eg</td></tr><tr><td>7</td><td>gagging due to under sedation/paralysis, all of which</td><td></td></tr><tr><td colspan=\"3\">propofol 5-10mg/hr and vecuronium 10mg</td></tr><tr><td colspan=\"3\">will further increase ICP</td></tr><tr><td>8</td><td>Decompress bladder with IDC</td><td>Avoid hypertension due to bladder distension</td></tr><tr><td>9</td><td>Decompress stomach</td><td>Minimise risk of aspiration, optimise ventilation</td></tr><tr><td colspan=\"3\">Adjust FiO2 to achieve sats &gt;95% and avoid hyperoxia</td></tr><tr><td>10</td><td>Maintain adequate oxygenation</td><td></td></tr><tr><td colspan=\"3\">(&lt;99%)</td></tr><tr><td colspan=\"3\">Keep Hb &gt;10g/dl to ensure adequate O2 delivery,</td></tr><tr><td>11</td><td>Treat anaemia</td><td></td></tr><tr><td colspan=\"3\">transfuse blood as needed</td></tr><tr><td>Treat seizures -  midaz 5mg if seizing, then</td><td>Avoid further brain injury from seizure activity - no</td><td></td></tr><tr><td colspan=\"3\">12</td></tr><tr><td>phenytoin 20mg/kg</td><td>evidence to support prophylactic anti-epileptics</td><td></td></tr><tr><td colspan=\"3\"><span class=\"answer-source-red\">Must name at least 2 methods to avoid raised ICP (CO2, ETT ties, collar), must name BP control, </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">3.1 Hyperventilate to pCO2 30-35</div><div class=\"answer-line\">3. 2 Give mannitol 20% 0.5-1g/kg</div><div class=\"answer-line\">3.3 Give hypertonic saline e.g. 250ml of 3% saline</div><div class=\"answer-line\"><span class=\"answer-source-red\">Either 3.1 (1 mark)  and  3.2 or 3.3 (1 mark) –including strength and dose/kg</span></div><div class=\"answer-line\">SAQ 13 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 30-year-old Nepalese man presents with fever and confusion. He is noted to have dullness to percussion on his right lung base. His CxR is attached: *See image on page 14 in separate book* You do a pleural tap.","parts":[{"id":"a","label":"Part A","prompt":"List five investigations you would order on the pleural fluid and justify your responses. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 2 biochemical features that differentiate a transudate from an exudate. (2 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Name 3 common causes of transudates and 3 common causes of exudates that cause pleural\neffusions. (3 marks) Transudate Exudate"}],"propPages":["asset:img8b72708d4da1b27ef0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pleural fluid :  protein, LDH, glucose ( &lt;3.3 mmol/L associated with empyema, rheumatoid, SLE TB,</div><div class=\"answer-line\">malignancy ), pH (&lt;7.2 indicates pleural infection and indication for drainage if parapneumonic).</div><div class=\"answer-line\">Wcc and differentials</div><div class=\"answer-line\">Cytology</div><div class=\"answer-line\">HCT if suspect haemothorax ( if bloody HCT &lt;1% not significant, 1-20% malignancy/PE/trauma, &gt;50%</div><div class=\"answer-line\">haemothorax).</div><div class=\"answer-line\">Gram stain and culture, + AFB</div><div class=\"answer-line\">Serum protein and LDH for comparison</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Light’s criteria :</div><div class=\"answer-line\">Exudate if one or more of the following criteria are met (sens 98%, spec 83%)</div><div class=\"answer-line\">pleural fluid protein : serum protein &gt;0.5</div><div class=\"answer-line\">pleural fluid LDH: serum LDH &gt;0.6</div><div class=\"answer-line\">pleural fluid  LDH &gt; 2/3 upper limit of normal serum LDH</div><div class=\"answer-line\">additional criteria if results equivocal:</div><div class=\"answer-line\">serum albumin – pleural albumin &lt; 1.2 g/dL</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Transudates : Common causes: CCF, cirrhosis, hypoalbuminaemia, (other : hypothyroidism,</div><div class=\"answer-line\">nephrotic syndrome)</div><div class=\"answer-line\">Exudates : common : pneumonia (bacterial, fungal, TB) ; malignancy ; pulmonary infarction form PE.</div><div class=\"answer-line\">(others : oesophageal rupture, pancreatitis, intra abdominal abscess, collagen vascular diseases, post</div><div class=\"answer-line\">CABG, asbestos, sarcoidosis)</div><div class=\"answer-line\">SAQ 14  image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 10-year-old boy presents to the Emergency department with abdominal pain.","parts":[{"id":"a","label":"Part A","prompt":"What clinical features of the history and examination make a diagnosis of appendicitis more likely? (4 marks) After history and physical examination, you decide the most likely diagnosis is appendicitis but want to exclude other causes of abdominal pain in children."},{"id":"b","label":"Part B","prompt":"List four tests and the diagnosis they would exclude in the table below. (4 marks) Test Diagnosis After referral to the Surgical registrar on call you are asked to keep the child nil by mouth."},{"id":"c","label":"Part C","prompt":"Please prescribe maintenance fluid in the table below for the next 12 hours. Assume only 1000ml bags of intravenous fluid are available. (2 marks) Total Rate"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Right iliac fossa pain</span>, Pain migrating to right iliac fossa, duration less than 3 days, anorexia,</div><div class=\"answer-line\">vomiting, fever, right iliac fossa tenderness, pain on hopping, pain on coughing, pain on</div><div class=\"answer-line\">movement or walking</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Test</td><td>Diagnosis</td></tr><tr><td><span class=\"answer-source-red\">serum glucose</span></td><td>Diabetes Mellitus / diabetic</td></tr><tr><td colspan=\"2\">ketoacidosis</td></tr><tr><td><span class=\"answer-source-red\">urine analysis (dipstick)</span></td><td>urinary tract infection</td></tr><tr><td>liapse / amylase</td><td>pancreatitis</td></tr><tr><td>Chest xray</td><td>Perforation / LRTI</td></tr><tr><td>ultrasound</td><td>intussusception</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Additive and</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 25-year-old gym owner presents to ED with a left lower leg injury after being tackled at football training. Impact was lateral with the opponent landing on him. He has intense pain and swelling of the lower leg. There is no disruption of skin. The initial X rays are provided. *See images on pages 15 - 20 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities evident on the images. (5 marks)"},{"id":"b","label":"Part B","prompt":"What are the potential acute complications with this injury? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 methods of providing analgesia in this case. (3 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 3 methods of assessing for tissue compartment syndrome. (3 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________"}],"propPages":["asset:img61c40bfc6a187e1ac8","asset:imgc08a403ff60f25082e","asset:img40a3e85ff36897bbba","asset:img7e492381c6d88d8d8f","asset:img59c88a166c078b89c5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Answers</td></tr><tr><td colspan=\"2\">a) Abnormalities</td></tr><tr><td>•</td><td>Minimally displaced Weber C spiral fracture of the proximal fibula (Maisonneuve fracture).</td></tr><tr><td>•</td><td>Lateral and posterior subluxation of the talus &gt; 5mm.</td></tr><tr><td>•</td><td>Disruption of the tibiofibular syndesmosis</td></tr><tr><td>•</td><td>Posterior malleolar fracture of the tibia with &gt;5mm displacement of the fragment.</td></tr><tr><td>•</td><td>Associated soft tissue oedema</td></tr><tr><td colspan=\"2\">Score 5/5. Must have all answers in bold or maximum score 2/5.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Compartment syndrome</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Common/deep peroneal nerve injury</div><div class=\"answer-line\">Score 2/2</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pharmacological –</div><div class=\"answer-line\">a. Inhalational - Nitrous oxide/methoxyflurane</div><div class=\"answer-line\">b. Parenteral – opiates/ NSAIDS/ketamine</div><div class=\"answer-line\">c. Enteral – paracetamol/ NSAIDs/opiates</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Physical – reduction and splinting</div><div class=\"answer-line\">Score 3/3. Must include answer in bold or maximum score 1/3</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Clinical – Pain, Paraesthesia, Paralysis, Pallor, Poikilothermia (+/- pulselessness)</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Pressure manometers – commercial</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Lab tests – CPK</div><div class=\"answer-line\">Score 3/3. Must include Clinical with at least the 5 Ps or maximum score is 1/3.</div><div class=\"answer-line\">SAQ 16 images</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 4-year-old boy is brought in to the Emergency Department by his concerned parents. He has been unwell with a fever for 6 days. He has a diffusely erythematous pharynx and a unilateral 3cm cervical lymph node on the right. *See images on pages 21 & 22 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"Give 4 differential diagnosis. (2 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) __________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Outline the typical features of this condition. (4 marks)"},{"id":"d","label":"Part D","prompt":"List 2 potential complications. (2 marks)\nCardiac complication Non-cardiac complication"},{"id":"e","label":"Part E","prompt":"Outline your management? (4 marks) ~END OF PART 2~ TRIAL FELLOWSHIP EXAMINATION\nSt George Hospital 2016.1\nWRITTEN EXAMINATION Short Answer Questions\nPART 3\nInstructions:  There are 3 separate books, each worth 100 marks (for a total of 300 marks).  Time Allowed: 3 hours.  Each booklet should be completed in 1 hour.  All images are reproduced in the accompanying ‘props’ booklet.  Answer each question on the provided examination paper.  Write your name on each page in the space provided. ~BLANK PAGE~"}],"propPages":["asset:imgb093dc0846b4cefd87","asset:imge585b5a8dba393f380"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Kawasaki disease</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">a. Viral exanthems</div><div class=\"answer-line\">b. Strep disease: eg scarlet fever, toxic shock syndrome</div><div class=\"answer-line\">c. Staph disease: eg scalded skin syndrome, TSS</div><div class=\"answer-line\">d. Steven Johnsons syndrome</div><div class=\"answer-line\">e. Drug reaction</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">2. Clinical critieria to diagnose ‘typical’ KD:</div><div class=\"answer-line\">A. fever for 5 or more days, and</div><div class=\"answer-line\">B. at least 4 out of 5 of:</div><div class=\"answer-line\">a. bilateral non-exudative conjunctivits</div><div class=\"answer-line\">b. oropharyngeal mucous membrane changes: pharyngeal erythma,</div><div class=\"answer-line\">red/cracked lips, ‘strawberry’ tongue</div><div class=\"answer-line\">c. cervical lymphadenopathy</div><div class=\"answer-line\">d. peripheral extremity changes: acute: diffuse erythema and swelling</div><div class=\"answer-line\">of hands/feet, convalescent phase: desquamation</div><div class=\"answer-line\">e. polymorphous generalized rash</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">The primary complications of Kawasaki disease (KD) are cardiac sequelae, although noncardiac</div><div class=\"answer-line\">complications also may occur (table 1). (See&#x27;Introduction&#x27; above.)</div><div class=\"answer-line\">●KD shock syndrome (KDSS), defined as sustained systolic hypotension or clinical signs of poor</div><div class=\"answer-line\">perfusion, is a potentially life-threatening complication. (See &#x27;Shock&#x27; above.)</div><div class=\"answer-line\">●Macrophage activation syndrome (MAS) is a rare and potentially life-threatening complication</div><div class=\"answer-line\">of KD that should be considered in patients with persistent fever after intravenous immune</div><div class=\"answer-line\">globulin (IVIG) therapy. (See &#x27;Macrophage activation syndrome&#x27; above and &quot;Clinical features and</div><div class=\"answer-line\">diagnosis of hemophagocytic lymphohistiocytosis&quot;, section on &#x27;Rheumatologic disorders/MAS&#x27;.)</div><div class=\"answer-line\">●The major complication of KD is coronary artery (CA) aneurysms. However, other cardiac</div><div class=\"answer-line\">sequelae can occur, including decreased myocardial contractility, coronary arteritis without</div><div class=\"answer-line\">aneurysms, mild valvular regurgitation (primarily mitral valve involvement), and pericardial</div><div class=\"answer-line\">effusion. Acute myocardial infarction is the main cause of death in KD. (See &#x27;Cardiac</div><div class=\"answer-line\">complications&#x27; above and &quot;Cardiovascular sequelae of Kawasaki disease&quot;.)</div><div class=\"answer-line\">●Vascular changes also may occur in peripheral arteries. Peripheral arterial obstruction can lead</div><div class=\"answer-line\">to ischemia and gangrene. (See &#x27;Noncoronary vascular involvement&#x27; above.)</div><div class=\"answer-line\">●Urinary abnormalities and renal disease, with the exception of sterile pyuria, are uncommonly</div><div class=\"answer-line\">associated with KD. (See &#x27;Urinary abnormalities and renal disease&#x27; above.)</div><div class=\"answer-line\">●Children with KD may present with a wide variety of gastrointestinal manifestations, rarely</div><div class=\"answer-line\">including acute abdominal catastrophes. (See&#x27;Gastrointestinal abnormalities&#x27; above.)</div><div class=\"answer-line\">●Sensorineural hearing loss, usually transient and asymptomatic, can be seen following KD.</div><div class=\"answer-line\">(See &#x27;Central nervous system&#x27; above.)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">1. Specific management: <strong>IV immunoglobulin</strong> with high dose <strong>aspirin</strong>, echo.</div><div class=\"answer-line\"><strong>Supportive</strong>; Fluids/analgesia/etc if indicated.</div><div class=\"answer-line\">Dispostion: Admit</div><div class=\"answer-line\"><strong>SAQ 17 images </strong></div><div class=\"answer-line\">SAQ 17 images</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 74-year-old woman presents with light-headedness, lethargy and palpitations.\nHer vital signs are BP 100/60, HR 124/min, temp 37, SaO2 99% on room air.\nShe has a past medical history of type 2 diabetes, hypertension and has a pacemaker for heart block. Her pacemaker card indicates she has a DDD pacemaker.","parts":[{"id":"a","label":"Part A","prompt":"Describe the DDD function of her pacemaker. (2 marks) *See ECG on page 23 in separate book*"},{"id":"b","label":"Part B","prompt":"Describe her ECG. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 differential diagnoses (2 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 4 management steps you would initiate for her. (4 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) ___________________________________________________________________________"}],"propPages":["asset:img978bd6f7f90fcfb78b","asset:img96d90fce5f2abf7b32"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">a. Dual (atrial and ventricular) chamber pacing. (0.5)</div><div class=\"answer-line\">b. Dual (atrial and ventricular) chamber sensing. (0.5)</div><div class=\"answer-line\">c. Dual response to sensing in that it will trigger or inhibit pacing depending on</div><div class=\"answer-line\">the underlying rhythm. (1)</div><div class=\"answer-line\">Her ECG is enclosed.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">i. Broad complex tachycardia (HR 120/min) with a ventricular pacing</div><div class=\"answer-line\">spike before every complex. (1)</div><div class=\"answer-line\">ii. Absence of p wave before each ventricular pacing spike indicating</div><div class=\"answer-line\">that the pacemaker is not triggered by a native atrial rhythm. (1)</div><div class=\"answer-line\">iii. Absence of atrial spike before each ventricular pacing spike indicating</div><div class=\"answer-line\">that there is no atrial pacing. (1)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>Pacemaker mediated tachycardia (PMT).  A re-entry tachycardia is</td></tr><tr><td colspan=\"2\">created by the pacemaker forming an anterograde pathway and the</td></tr><tr><td colspan=\"2\">AV node acting as a retrograde pathway. The retrograde p wave is</td></tr><tr><td colspan=\"2\">sensed as native atrial activity and further ventricular pacing is</td></tr><tr><td colspan=\"2\">propogated causing the inappropriate tachycardia. (1)</td></tr><tr><td>ii.</td><td>Sensor-induced tachycardia.  The sensor may misfire from ‘noise’</td></tr><tr><td colspan=\"2\">such as vibrations, loud noises, hyperventilation, surgical</td></tr><tr><td colspan=\"2\">electrocautery, etc. (1)</td></tr><tr><td>iii.</td><td>Lead displacement dysrhythmia. A dislodged pacemaker lead may</td></tr><tr><td colspan=\"2\">be irritating the myocardium. (1)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">a. Urgent cardiology referral and pacemaker interrogation. (1)</div><div class=\"answer-line\">b. Apply a magnet over the pacemaker which will inhibit sensing and activate</div><div class=\"answer-line\">asynchronous ventricular pacing at the preset demand rate. This will block the</div><div class=\"answer-line\">anterograde circuit and can terminate PMT. (1*)</div><div class=\"answer-line\">c. Vagal manoeuvre (carotid sinus, vasalva) can block AV conduction to terminate</div><div class=\"answer-line\">PMT. (1)</div><div class=\"answer-line\">d. Adenosine or verapamil can block AV conduction to terminate PMT.  (1)</div><div class=\"answer-line\">e. CXR looking for fractured or displaced pacemaker leads. (1)</div><div class=\"answer-line\">f. EUCs looking for hyper/hypokalaemia, hypomagnesaemia. (1)</div><div class=\"answer-line\">SAQ 18 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A four-year-old girl presents to the Emergency Department with an isolated Left Elbow injury after falling 2 metres from a climbing frame in a local park. She is in severe pain and refusing to move her arm.","parts":[{"id":"a","label":"Part A","prompt":"Describe how you would manage her pain giving doses and routes of drugs. (4 marks) *See image on page 24 in separate book*"},{"id":"b","label":"Part B","prompt":"Describe four abnormalities shown. (4 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) ___________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List two immediate / early complications of her injury. (2 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________"}],"propPages":["asset:imgd1b3497e5861d9c69e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Intranasal fentanyl 1-2microgrammes / kg,  </span></div><div class=\"answer-line\">Intravenous Morphine 0.05-0.1mg / kg</div><div class=\"answer-line\">Oral or Rectal Paracetamol 15-30mg / kg</div><div class=\"answer-line\">Oral Ibuprofen 5 – 10mg / kg</div><div class=\"answer-line\">Oral Oxycodone 0.1mg/kg</div><div class=\"answer-line\">Inhaled nitrous oxide</div><div class=\"answer-line\"><span class=\"answer-source-red\">Splint arm / sling arm / apply above elbow backslab / protect elbow </span></div><div class=\"answer-line\">Distraction / play therapy / keep parent with child</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Abnormal / pathological anterior fat pad</div><div class=\"answer-line\"><span class=\"answer-source-red\">Posterior fat pad </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Transverse fracture of distal humerus </span></div><div class=\"answer-line\">Dorsal angulation of distal fragment</div><div class=\"answer-line\">Abnormal anterior humeral line</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Brachial artery injury / dissection,</div><div class=\"answer-line\">Compound or open injury</div><div class=\"answer-line\">Peripheral nerve injury</div><div class=\"answer-line\">Tendon injury</div><div class=\"answer-line\">SAQ 19  image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 24-year-old man with a history of hydrocephalus presents with headache, malaise and fever. He has a venticuloperitoneal shunt.","parts":[{"id":"a","label":"Part A","prompt":"Aside from the peritoneal cavity, list 2 other potential sites for the drainage limb of a ventricular shunt (2 marks). (1) ___________________________________________________________________________ (2) ___________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Apart from infection, list 3 causes of shunt obstruction. (3 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"What is the most commonly cultured micro-organism in CSF shunt infections? (1 mark)"},{"id":"d","label":"Part D","prompt":"What is the role of lumbar puncture in a patient with a ventriculoperitoneal shunt? (1 mark) *See CT on page 25 in separate book*"},{"id":"e","label":"Part E","prompt":"What is the diagnosis? (2 marks)"}],"propPages":["asset:img0702f6403429ca8635"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Prox: tissue debris, choroid plexus, clot, infection, catheter tip migration, localized immune</div><div class=\"answer-line\">response to tubing</div><div class=\"answer-line\">Distal: Kinking/disconnection of tube, pseudocyst formation, infection</div><div class=\"answer-line\">What is the most commonly cultured micro-organism in CSF shunt infections? (1 mark)</div><div class=\"answer-line\">Staph epidermidis</div><div class=\"answer-line\">What is the role of lumbar puncture in a patient with a ventriculoperitoneal shunt? (1 mark)</div><div class=\"answer-line\">No role,  May be negative in presence of shunt infection.</div><div class=\"answer-line\">His CT image is attached. What is the diagnosis ( 2 marks)</div><div class=\"answer-line\">1. Slit ventricle syndrome (2 marks).  often presents with waxing and waning symptoms. The CT</div><div class=\"answer-line\">is often helpful in distinguishing it from other causes of malfunction.  Overdrainage and the</div><div class=\"answer-line\">slit ventricle syndrome are seen in approximately 5% of patients with shunts. Because of</div><div class=\"answer-line\">overdrainage, the tissues actually occlude the orifices of the proximal shunt apparatus. As</div><div class=\"answer-line\">intracranial pressure increases, the same occluding tissue is disengaged, which allows</div><div class=\"answer-line\">drainage to resume. This phenomenon is cyclical and is responsible for the episodic or</div><div class=\"answer-line\">waxing and waning aspect of the presenting complaint. Patients present with episodes of</div><div class=\"answer-line\">elevated intracranial pressure caused by a transient obstruction of the ventricular catheter</div><div class=\"answer-line\">from a collapsed ventricle. Decreased cerebral compliance may prevent the ventricles from</div><div class=\"answer-line\">fully expanding as intracranial pressure and volume increase, which further contributes to</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Pleural cavity, right atrium, ureter, gall bladder (2 marks)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Prox: tissue debris, choroid plexus, clot, infection, catheter tip migration, localized immune</div><div class=\"answer-line\">response to tubing</div><div class=\"answer-line\">Distal: Kinking/disconnection of tube, pseudocyst formation, infection</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Staph epidermidis</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">No role,  May be negative in presence of shunt infection.</div><div class=\"answer-line\">1. Slit ventricle syndrome (2 marks).  often presents with waxing and waning symptoms. The CT</div><div class=\"answer-line\">is often helpful in distinguishing it from other causes of malfunction.  Overdrainage and the</div><div class=\"answer-line\">slit ventricle syndrome are seen in approximately 5% of patients with shunts. Because of</div><div class=\"answer-line\">overdrainage, the tissues actually occlude the orifices of the proximal shunt apparatus. As</div><div class=\"answer-line\">intracranial pressure increases, the same occluding tissue is disengaged, which allows</div><div class=\"answer-line\">drainage to resume. This phenomenon is cyclical and is responsible for the episodic or</div><div class=\"answer-line\">waxing and waning aspect of the presenting complaint. Patients present with episodes of</div><div class=\"answer-line\">elevated intracranial pressure caused by a transient obstruction of the ventricular catheter</div><div class=\"answer-line\">from a collapsed ventricle. Decreased cerebral compliance may prevent the ventricles from</div><div class=\"answer-line\">fully expanding as intracranial pressure and volume increase, which further contributes to</div><div class=\"answer-line\">ventricular collapse. The rate of this complication is lower for currently used shunt systems</div><div class=\"answer-line\">with antisiphon devices and programmable shunt valves</div><div class=\"answer-line\">Author: M Taliana, Maitland Hospital</div><div class=\"answer-line\">Source: Ch 169 Tintinalli</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 62-year-old male with a history of chronic pancreatitis presents to the Emergency Department with several days of nausea and vomiting. His biochemistry profile is attached:","parts":[{"id":"a","label":"Part A","prompt":"Interpret the abnormalities in the results. (3 marks)"},{"id":"b","label":"Part B","prompt":"Give likely underlying causes for the main metabolic acid-base disturbances. (3 marks)"},{"id":"c","label":"Part C","prompt":"Describe the clinical features of severe hypocalcaemia. (2 marks)"},{"id":"d","label":"Part D","prompt":"Outline your management of symptomatic hypocalcaemia. (2 marks)"}],"propPages":["asset:imgf03d525b325f955b6d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">a) Severe metabolic alkalosis with respiratory compensation</div><div class=\"answer-line\">High anion gap (approx. 31) metabolic acidosis</div><div class=\"answer-line\">Profound hypochloraemia</div><div class=\"answer-line\">Gastric losses and fluid depletion causing chloride loss and metabolic alkalosis</div><div class=\"answer-line\">Metabolic acidosis secondary to renal failure (acute? Acute on chronic?) +/- sepsis</div><div class=\"answer-line\">from pancreatitis and/or gastro-enteritis</div><div class=\"answer-line\">CO2 retention as compensation for severe metabolic alkalosis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">a) Causes of a hypochloraemic metabolic alkalosis:</div><div class=\"answer-line\">Recurrent vomiting</div><div class=\"answer-line\">Gastric acid loss,</div><div class=\"answer-line\">Diuretic-induced alkalosis (loop or thiazide diuretics)</div><div class=\"answer-line\">Posthypercapnic metabolic alkalosis.</div><div class=\"answer-line\">CLD, cystic fibrosis, and laxative abuse are also potential causes.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">a) Carpopedal spasm, tetany, seizures, decreased cardiac function, or prolonged QT</div><div class=\"answer-line\">interval</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">a) Intravenous calcium replacement with either 10% calcium gluconate or 10% calcium</div><div class=\"answer-line\">chloride, followed by a calcium infusion.</div><div class=\"answer-line\">Hypomagnaesemia should also be treated, with IV magnesium supplementation</div><div class=\"answer-line\">SAQ 21 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"You are preparing a presentation on the management of patients who present to the emergency department in labour when delivery is imminent.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table describing signs and management of common problems in labour. (12 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">managment</td></tr><tr><td>Nuchal Cord</td><td>Cord around baby’s head</td><td>If loose,can pull over baby’s head. If tight then</td></tr><tr><td colspan=\"3\">place 2 clamps and cut between them.</td></tr><tr><td>Shoulder Dystocia</td><td>“turtle sign”, head comes</td><td>Get help</td></tr><tr><td colspan=\"3\">out but then goes back in</td></tr><tr><td colspan=\"3\">Drain Bladder</td></tr><tr><td colspan=\"3\">Anterior shoulder impacted</td></tr><tr><td colspan=\"3\">Consider episiotomy</td></tr><tr><td colspan=\"3\">below pubic bone</td></tr><tr><td colspan=\"3\">Mc Robert’s technique – flex knees to chest</td></tr><tr><td colspan=\"3\">with pt on her back</td></tr><tr><td colspan=\"3\">Suprapubic pressure</td></tr><tr><td colspan=\"3\">Position mother on hands and knees with</td></tr><tr><td colspan=\"3\">knees to chest</td></tr><tr><td colspan=\"3\">Break clavicle if everything else fails (pinch</td></tr><tr><td colspan=\"3\">midpoint of clavicle and snap it).</td></tr><tr><td>Cord Prolapse</td><td>Bluish gray cord of tissue in</td><td>This can compress cord, causing decreased</td></tr><tr><td>vagina</td><td>oxygen to baby when head engages.</td><td></td></tr><tr><td colspan=\"3\">Needs surgical delivery.</td></tr><tr><td colspan=\"3\">Tell mother to stop pushing, elevate hips, push</td></tr><tr><td colspan=\"3\">head up.</td></tr><tr><td colspan=\"3\">Give mother oxygen</td></tr><tr><td>Post Partum</td><td>Bleeding after delivery</td><td>External massage of uterine fundus</td></tr><tr><td colspan=\"3\">Haemorrhage</td></tr><tr><td colspan=\"3\">Inspect for tears</td></tr><tr><td colspan=\"3\">Inspect placenta</td></tr><tr><td colspan=\"3\">Bimanual compression</td></tr><tr><td colspan=\"3\">oxytocin</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"You are the in-charge consultant at an urban district hospital. You receive a batcall about a 2-year-\n• ld who has been dragged unconscious from a backyard pool. It is the middle of winter.\nHis vital signs en route are:\n\nHR\n\nGCS\nUnresponsive\n\nBP\n70/40\n\nTemp\n30 degrees O2 sats 90% (bag valve mask Fi02 1.0)","parts":[{"id":"a","label":"Part A","prompt":"List 4 predictors of poor outcome in drowning. (4 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) ___________________________________________________________________________ You intubate this child on arrival. *See his initial CXR on page 27 in separate book*"},{"id":"b","label":"Part B","prompt":"List 2 relevant features at this stage of the patient’s management. (2 marks)\n(1) ___________________________________________________________________________ (2) ___________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"What ventilation strategies would you use? (2 marks)"},{"id":"d","label":"Part D","prompt":"What are your other initial management priorities? (3 marks)"}],"propPages":["asset:imgec20588bf532a7edab"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Long immersion time &gt; 10 mins</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Delay to CPR</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Time to first breath</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Coma on arrival in ED</td></tr><tr><td>v)</td><td>Presence of cardiac arrest at scene</td></tr><tr><td>vi)</td><td>Water temperature – cold is more neuroprotective</td></tr><tr><td>vii)</td><td>Severe metabolic acidosis</td></tr><tr><td colspan=\"2\">You intubate this child on arrival.  This is his initial CXR.  List 2 relevant features at this stage of the</td></tr><tr><td colspan=\"2\">patient’s management (2 marks).</td></tr><tr><td>i)</td><td>Bilateral coalescing pulmonary infiltrates – concern for ARDS (must mention)</td></tr><tr><td>ii)</td><td>ETT appropriately placed</td></tr><tr><td>iii)</td><td>NGT below diaphragm  - aspiration risk and affect on ventilation if GIT no</td></tr><tr><td colspan=\"2\">decompressed</td></tr><tr><td colspan=\"2\">What ventilation strategies would you use ( 2 marks)</td></tr><tr><td colspan=\"2\">Low volume ventilation</td></tr><tr><td colspan=\"2\">ARDS ventilation</td></tr><tr><td colspan=\"2\">What are your other initial management priorities ( 3 marks)</td></tr><tr><td colspan=\"2\">_________________________________________________________________________</td></tr><tr><td colspan=\"2\">_________________________________________________________________________</td></tr><tr><td colspan=\"2\">_________________________________________________________________________</td></tr><tr><td>i)</td><td>Protective lung ventilation strategies and maintenance of oxygenation</td></tr><tr><td colspan=\"2\">Justification:  ARDS/ALI, VQ mismatch predicted given CXR, prevention of</td></tr><tr><td colspan=\"2\">secondary brain injury from hypercarbia/hypoxia</td></tr><tr><td>ii)</td><td>Cardiovascular support and fluid resuscitation</td></tr><tr><td colspan=\"2\">Justification:  hypovolaemia (from cold diuresis +/- hydrostatic pressure of</td></tr><tr><td colspan=\"2\">water on the body following prolonged immersion) and arrhythmias predicted.</td></tr><tr><td colspan=\"2\">Prevention of secondary brain injury from hypotension.</td></tr><tr><td>iii)</td><td>Rewarming to 34 degrees and prevention of shivering</td></tr><tr><td colspan=\"2\">Justification:  To prevent organ/systemic complications of hypothermia  -</td></tr><tr><td colspan=\"2\">CNS/resp/metabolic/GI/haematological (coagulopathy).</td></tr><tr><td>iv)</td><td>Disposition planning and contacting retrieval services</td></tr><tr><td colspan=\"2\">Justification:  Patient requires paediatric ICU management at a tertiary centre,</td></tr><tr><td colspan=\"2\">may require haemodialysis/ECMO</td></tr><tr><td colspan=\"2\"><strong>SAQ 23 image </strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 60-year-old man with a past history of type 2 diabetes presents after being found on the floor by his elderly mother. He has recently been unwell with vomiting for the last 3 weeks.\nHis vital signs are:\n\nBP 65/30\n\nGCS 13\nPulse 120 regular\nOxygen saturations 100% on 15 L NRM.\n*See arterial blood gas on page 28 in separate book*","parts":[{"id":"a","label":"Part A","prompt":"Interpret the abnormalities in the above results. (4 marks)"},{"id":"b","label":"Part B","prompt":"How would you initially manage these abnormalities? (3 marks ) The patient’s GCS deteriorates to 5 and he begins vomiting."},{"id":"c","label":"Part C","prompt":"What is your plan with regards to intubating this patient, and what ventilation strategy would you employ? (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Severe metabolic acidosis</div><div class=\"answer-line\">Some respiratory compensation (not fully compensated, expected CO2  13)</div><div class=\"answer-line\">Hyperglycaemia , ?DKA</div><div class=\"answer-line\">Renal impairment (Cr 246)</div><div class=\"answer-line\">Severe metabolic acidosis , multifactorial : likely sec DKA, ARF .</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">IV fluid bolus -500ml – 1 L initially, then repeat as needed (note severe hypotension)</div><div class=\"answer-line\">May need inotropic support</div><div class=\"answer-line\">Insulin infusion 5 units/ hr, aim slow reduction of BSL</div><div class=\"answer-line\">K+ replacement once K+ &lt; 4</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- prepare for possible arrest</div><div class=\"answer-line\">- have fluids and inotropes running prior to intubation</div><div class=\"answer-line\">- most senior doctor intubating, video larygoscopy if available</div><div class=\"answer-line\">- drugs : ketamine 1mg/kg, suxamethonium</div><div class=\"answer-line\">- high ventilation rate, as need to maintain low CO2 to avoid worsening acidosis.</div><div class=\"answer-line\">- early referral to ICU for management of ventilation on ICU ventilator.</div><div class=\"answer-line\">SAQ 24 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false,"investigationTables":[{"id":"arterial-blood-gas-poct","title":"Arterial blood gas and point-of-care results","headers":["Test","Flag","Result","Unit"],"rows":[["Arterial Blood pH POCT","L","6.865",""],["Arterial Blood pO₂ POCT","H","417.0","mmHg"],["Arterial Blood pCO₂ POCT","L","18.7","mmHg"],["Arterial Blood O₂ Saturation POCT","","99.2","%"],["Arterial Blood HCO₃ POCT","L","3.2","mmol/L"],["Arterial Blood Base Excess POCT","L","-27.2","mmol/L"],["Arterial Blood Oxyhaemoglobin POCT","","97.2","%"],["Arterial Blood Inspired Oxygen POCT","","100","%"],["Arterial Blood Haemoglobin POCT","L","124","g/L"],["Arterial Blood Reduced Haemoglobin POCT","","0.8","%"],["Arterial Blood Methaemoglobin POCT","H","0.9","%"],["Arterial Blood Carboxyhaemoglobin POCT","","1.1","%"],["Arterial Blood Creatinine POCT","H","246","µmol/L"],["Arterial Blood Sodium POCT","","142","mmol/L"],["Arterial Blood Potassium POCT","","4.6","mmol/L"],["Arterial Blood Chloride POCT","","107","mmol/L"],["Arterial Blood Calcium Ionised POCT","","1.30","mmol/L"],["Arterial Blood Glucose POCT","H","31.0","mmol/L"],["Arterial Blood Lactate POCT","L","1.7","mmol/L"]]}]},{"number":25,"title":"","stemText":"A 34-year-old man presents 10 days after a business trip to Papua New Guinea. He has had fevers, malaise, generalised aches and frequent episodes of diarrhoea.\n\nHR 130\n\nBP 100/50\n\nTemp 38\n\nSats 98% on air.","parts":[{"id":"a","label":"Part A","prompt":"List 10 potential causes of fever & illness in this man. (5 marks)"},{"id":"b","label":"Part B","prompt":"What blood tests will you request? (3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 major complications of severe Plasmodium falciparum malaria. (4 marks)"},{"id":"d","label":"Part D","prompt":"What are the two main choices for the urgent initial treatment of severe Plasmodium falciparum malaria? (2 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Malaria</div><div class=\"answer-line\">Dengue</div><div class=\"answer-line\">Typhoid/paratyphoid</div><div class=\"answer-line\">GIT infections – cholera, shigella, salmonella, E coli diarrhoea, giardiasis etc</div><div class=\"answer-line\">Viral hepatitis</div><div class=\"answer-line\">Typhus/rickettsial diseases</div><div class=\"answer-line\">Melioidosis</div><div class=\"answer-line\">Japanese or Australian (Murray Valley) encephalitis</div><div class=\"answer-line\">Non-exotic/”normal” infections – LRTI, UTI, STI, cellulitis etc etc etc</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Investigation</td><td>Justification</td></tr><tr><td>FBC</td><td>Part of fever workup. ?malaria \u0001 anaemia</td></tr><tr><td>EUC</td><td>Unwell, diarrhoea \u0001 potential derangement</td></tr><tr><td>LFT</td><td>Hepatitis possible</td></tr><tr><td>Blood culture</td><td>Part of workup</td></tr><tr><td>Malaria films</td><td>Ideally 3 sets over 48 hours (practice varies)</td></tr><tr><td>Falciparum +/- vivax antigen</td><td>&gt; 95% sensitive for PF</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Haemolysis/anaemia</div><div class=\"answer-line\">Splenic enlargement/rupture</div><div class=\"answer-line\">Cerebral malaria – delirium, coma, seizures</div><div class=\"answer-line\">ARF</div><div class=\"answer-line\">Non-cardiogenic pulmonary oedema</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Lactic acidosis</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">1. Artesunate (2.4mg/kg IV) then oral</div><div class=\"answer-line\">2. Quinine (20mg/kg IVI over 4 hours)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 32-year-old Aboriginal woman presents to the ED with lethargy. She is previously well, and has not been seen by medical services for the previous 10 years. Her VBG is attached:","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely cause for the abnormalities on the VBG? Describe and interpret the abnormalities. (5 marks)\nHer creatinine is 1842 with a urea of 62."},{"id":"b","label":"Part B","prompt":"List 4 possible causes for these findings in a 32-year-old Aboriginal woman, with the most common cause first. (3 marks) (1) ___________________________________________________________________________ (2) ___________________________________________________________________________ (3) ___________________________________________________________________________ (4) ___________________________________________________________________________ She becomes agitated and appears to be getting ready to leave the ED."},{"id":"c","label":"Part C","prompt":"What would be some strategies to stop her leaving? (4 marks) ~END~"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 32 yr old Aboriginal woman presents to the ED with lethargy. She is previously well, and has not</div><div class=\"answer-line\">been seen by medical services for the previous 10 yrs,</div><div class=\"answer-line\">Her VBG is attached.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Her creatinine is 1842 with a urea of 62</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">SAQ 26 image</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
